  // Only record interaction telemetry for edit tools where 100% of the tool
  // calls were accepted. Non-edit tools do not produce an interaction event.
  return isEdit && traceId && acceptedToolCalls / toolCalls.length >= 1
    ? createConversationInteraction(
        traceId,
        actionStatus || ActionStatus.ACTION_STATUS_NO_ERROR,
        ConversationInteractionInteraction.ACCEPT_FILE,
        String(acceptedLines),
        String(removedLines),
        language,
      )
    : undefined;
