function getLanguageFromFilePath(filePath: unknown): string | undefined {
  if (typeof filePath !== 'string') {
    return undefined;
  }

  const lastDot = filePath.lastIndexOf('.');
  if (lastDot === -1) {
    return undefined;
  }

  const extension = filePath.slice(lastDot).toLowerCase();
  switch (extension) {
    case '.ts':
      return 'TypeScript';
    case '.py':
      return 'Python';
    default:
      return undefined;
  }
}

